/**
 * 登录请求。密码相关字段要求使用 SM2(C1C3C2) 密文。
 */
export interface LoginRequest {
  /**
   * 登录账号
   * @example "admin"
   */
  loginAccount: string;
  /**
   * 使用当前公钥加密后的密码密文，格式为 SM2(C1C3C2)
   * @example "04A8E1F0B2C3D4E5F6A7B8C9D0"
   */
  passwordCiphertext: string;
  /**
   * 登录加密公钥版本标识
   * @example "login-key-202603"
   */
  keyId: string;
  /**
   * 防重放随机串，每次请求必须唯一
   * @example "9f3b3c2d6e7f4a1b8c9d0e1f2a3b4c5d"
   */
  nonce: string;
  /**
   * 秒级时间戳，用于时间窗校验
   * @example 1760000000
   */
  timestamp?: number;
}

/**
 * 当前登录用户修改密码请求。旧密码和新密码都要求使用 SM2(C1C3C2) 密文。
 */
export interface ChangePasswordRequest {
  /**
   * 旧密码密文，格式为 SM2(C1C3C2)
   * @example "04B1E2F3A4C5D6E7F8091A2B3C4D5E6F"
   */
  oldPasswordCiphertext: string;
  /**
   * 新密码密文，格式为 SM2(C1C3C2)
   * @example "04112233445566778899AABBCCDDEEFF"
   */
  newPasswordCiphertext: string;
  /**
   * 登录加密公钥版本标识
   * @example "login-key-202603"
   */
  keyId: string;
  /**
   * 防重放随机串，每次请求必须唯一
   * @example "0d1c2b3a4e5f60718293a4b5c6d7e8f9"
   */
  nonce: string;
  /**
   * 秒级时间戳，用于时间窗校验
   * @example 1760000000
   */
  timestamp?: number;
}

